using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

public static class RingCombatPresentationValidation
{
    public static bool Running {get;private set;}
    public static string Output {get;private set;}
    const string Base=".tools/ring-combat-1006/ui";
    [Serializable] sealed class Meta {public string folder,status,runtimeHash;}
    sealed class Host:MonoBehaviour{}
    static Transform Root=>GameObject.Find("Canvas").transform;
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static string Hash(string p){using var h=SHA256.Create();return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
    static IEnumerator Frame(){yield return new WaitForSecondsRealtime(.15f);yield return new WaitForEndOfFrame();Canvas.ForceUpdateCanvases();}
    public static void Run(){Check(Application.isPlaying&&!Running,"Play required");Running=true;Output=Base+"/"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ");Directory.CreateDirectory(Output+"/inputs");File.WriteAllText(Base+"/latest.txt",Output);File.WriteAllText(Output+"/result.txt","RUNNING");File.WriteAllText(Output+"/producer-hashes.tsv",string.Join("\n",new[]{"Assets/Scripts/Editor/RingCombatPresentationValidation.cs","Assets/Scripts/UI/ForgeBattlefieldController.Stack.cs","Assets/Scripts/UI/ForgeBattlefieldController.AbilityFace.cs","Assets/Scripts/UI/ForgeBattlefieldController.Emblems.cs","Assets/Scripts/UI/ForgeBattlefieldController.Arena.cs","Assets/Scripts/UI/ForgeBattlefieldController.CardSelection.cs","Assets/Scripts/UI/RingBearerIcon.cs","Assets/Scripts/Networking/ForgeWire.cs","Tools/ForgeBridge/java/mtgb/bridge/ForgeBridge.java"}.Select(p=>p+"\t"+Hash(p)))+"\n");var go=new GameObject("TriggerOrderValidation");go.AddComponent<Host>().StartCoroutine(Guard(Exercise(),go));}
    static IEnumerator Guard(IEnumerator e,GameObject go){Exception error=null;while(true){bool more=false;object current=null;try{more=e.MoveNext();if(more)current=e.Current;}catch(Exception ex){error=ex;break;}if(!more)break;if(current is IEnumerator nested){yield return Nested(nested,ex=>error=ex);if(error!=null)break;}else yield return current;}try{(e as IDisposable)?.Dispose();}catch(Exception ex){error??=ex;}File.WriteAllText(Output+"/result.txt",error==null?"PASS: current actual Ring inputs, three-language exact helper art/known unlocked rules and counters, exact bearer icon and native identity in both public battlefield perspectives, change/control/leave removal, same-printing different designation grouping adapter; actual bearer choice and loot card IDs by raycast, readonly/duplicate guards and fixed fonts through view-return, exact helper ability event/remembered identity on stack. Native effect outcomes separate; no network/privacy/full PASS.":"FAIL\n"+error);Running=false;UnityEngine.Object.Destroy(go);}
    static IEnumerator Nested(IEnumerator e,Action<Exception> fail){while(true){bool more=false;object current=null;try{more=e.MoveNext();if(more)current=e.Current;}catch(Exception ex){fail(ex);break;}if(!more)break;if(current is IEnumerator child)yield return Nested(child,fail);else yield return current;}}
    static void Click(Button b){var rect=(RectTransform)b.transform;var pointer=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(pointer,hits);Check(hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==b,"Blocked "+b.name);ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,pointer,ExecuteEvents.pointerClickHandler);}
    static IEnumerator Exercise(){
        var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("RingCombatBattlefield").AddComponent<ForgeBattlefieldController>();bool enabled=ui.enabled;ui.enabled=false;var module=EventSystem.current.currentInputModule;bool active=module!=null&&module.enabled;if(module!=null)module.enabled=false;string language=GamePreferences.Language;
        var states=new List<string>();var choices=new List<string>();var abilityInputs=new List<string>();
        try{
            foreach(string sample in new[]{"ring-level3-sacrifice","ring-level4-life-loss","ring-bearer-control","ring-bearer-change"}) {
                string area=sample=="ring-bearer-change"?"change-native":"current";var meta=JsonUtility.FromJson<Meta>(File.ReadAllText(".tools/ring-combat-1006/"+area+"/"+sample+"-result.json"));Check(meta.status=="PASS"&&meta.runtimeHash==JsonUtility.FromJson<Meta>(File.ReadAllText("ForgeRuntime/runtime.json")).runtimeHash,"Native proof stale");
                foreach(string name in new[]{"ready","combat-resolved","bearer-cleared","bearer-changed"}) {string p=meta.folder+"/"+name+".json";if(File.Exists(p)){states.Add(p);states.Add(meta.folder+"/"+name+"-other.json");}}
                if(sample=="ring-level4-life-loss"||sample=="ring-bearer-change")foreach(string name in new[]{"bearer-choice","loot-choice"}){string p=meta.folder+"/"+name+".json";if(File.Exists(p))choices.Add(p);}
                var steps=Directory.GetFiles(meta.folder,"step-*.json").Where(p=>!p.EndsWith("-other.json")).OrderBy(p=>int.Parse(Path.GetFileNameWithoutExtension(p).Split('-').Last())).ToArray();
                if(sample=="ring-bearer-change")states.Add(steps.First(p=>{var v=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));return v.players[0].ringLevel==1&&v.players[0].ringBearerId>0&&v.request.kind=="InputPassPriority"&&v.stackCount==0;}));
                if(sample.StartsWith("ring-level"))abilityInputs.AddRange(steps.Where(p=>JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p)).stackItems.Any(e=>e.source?.helperArtName=="The Ring")).GroupBy(p=>string.Join("|",JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p)).stackItems.Where(e=>e.source?.helperArtName=="The Ring").Select(e=>e.description))).Select(g=>g.First()));
            }
            foreach(string p in states.Concat(choices).Concat(abilityInputs).Distinct()){File.Copy(p,Output+"/inputs/"+Path.GetFileName(Path.GetDirectoryName(Path.GetDirectoryName(p)))+"-"+Path.GetFileName(p));File.AppendAllText(Output+"/input-hashes.tsv",p+"\t"+Hash(p)+"\n");}
            foreach(string lang in new[]{"zh-CN","en-US","ja-JP"}){
                int rev=GamePreferences.Revision;bool changing=GamePreferences.Language!=lang;GamePreferences.SetLanguage(lang);float deadline=Time.realtimeSinceStartup+20;while((!GamePreferences.Ready||changing&&GamePreferences.Revision==rev)&&Time.realtimeSinceStartup<deadline)yield return null;Check(GamePreferences.Ready,"Locale not ready");yield return Frame();
                foreach(string path in states){var view=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(path));ui.Present(view,view.seat,false,null,null,"");yield return Frame();foreach(var p in UnityEngine.Object.FindObjectsByType<ForgeBattlefieldCardPointer>(FindObjectsSortMode.None)){p.ResetHover();p.enabled=false;}
                    foreach(var player in view.players){foreach(var card in player.battlefield.Where(c=>c.creature)){var tile=Root.GetComponentsInChildren<Transform>().Single(t=>t.name=="Card_"+card.id);var icon=tile.Find("Visual/RingBearer/Icon");Check((icon!=null)==card.ringBearer&&card.ringBearer==(card.id==player.ringBearerId),"Bearer icon stale/wrong identity");if(icon!=null){var glyph=icon.GetComponent<RingBearerIcon>();var mesh=glyph.canvasRenderer.GetMesh();Check(mesh!=null&&mesh.vertexCount==160&&!glyph.raycastTarget&&((RectTransform)icon).rect.width==((RectTransform)icon).rect.height,"Ring mesh/distortion/raycast");}}
                        foreach(var marker in player.effectMarkers.Where(c=>c.helperArtName=="The Ring")){var tile=Root.GetComponentsInChildren<Transform>().Single(t=>t.name=="Card_"+marker.id);Check(SpecialEffectArt.TryLoad("The Ring",out var sprite)&&tile.Find("Visual/Border/Face").GetComponent<Image>().sprite==sprite,"Ring helper art");string rules=(string)typeof(ForgeBattlefieldController).GetMethod("MarkerRules",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{marker});Check(rules.Contains(player.ringTemptedCount.ToString())&&(lang=="en-US"?rules.Contains("Ring-bearer"):!rules.Contains("Ring-bearer")&&!rules.Contains("Whenever")&&!rules.Contains("Your")),"Unlocked rules/counter locale");}
                    }if(lang=="zh-CN"&&path.EndsWith("bearer-changed.json")){ScreenCapture.CaptureScreenshot(Output+"/bearer-changed.png");yield return Frame();}File.AppendAllText(Output+"/steps.log",lang+" state "+path+" PASS\n");
                }
                foreach(string path in choices)foreach(bool acting in new[]{true,false}){var view=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(path));int calls=0,last=-1;ui.Present(view,view.request.seat,acting,i=>{calls++;last=i;},null,"");yield return Frame();foreach(var p in UnityEngine.Object.FindObjectsByType<ForgeBattlefieldCardPointer>(FindObjectsSortMode.None)){p.ResetHover();p.enabled=false;}
                    bool direct=view.request.kind=="InputSelectCardsFromList";var option=direct?view.request.options.Single(o=>o.card!=null&&o.card.id==view.players[view.request.seat-1].hand.Last().id):view.request.options.First(o=>o.card!=null&&!string.IsNullOrEmpty(o.card.name));var tile=Root.GetComponentsInChildren<Transform>().Single(t=>t.name==(direct?"Card_":"ChoiceCard_")+option.card.id);var button=direct?tile.GetComponent<Button>():tile.Find("Artwork").GetComponent<Button>();Check(direct||button.interactable==acting,"Choice readonly gate");if(!direct){var panel=Root.GetComponentsInChildren<Transform>().Single(t=>t.name=="CardSelection");var prompt=panel.Find("Instruction").GetComponent<Text>();Check(!prompt.resizeTextForBestFit&&prompt.preferredHeight<=prompt.rectTransform.rect.height+1,"Ring instruction clips/shrinks");Check(panel.Find("Title").GetComponent<Text>().text==(lang=="zh-CN"?"选择持戒者":lang=="ja-JP"?"指輪所持者":"Ring-bearer"),"Ring choice title locale");}
                    var fonts=Root.GetComponentsInChildren<TMPro.TextMeshProUGUI>().Select(t=>t.fontSize).ToArray();ui.ViewBattlefield();yield return Frame();ui.RestoreBattlefieldWindows();yield return Frame();Check(fonts.SequenceEqual(Root.GetComponentsInChildren<TMPro.TextMeshProUGUI>().Select(t=>t.fontSize))&&calls==0,"Choice font/view submits");Click(button);int index=ui.OptionIndex(option.id);Check(acting?calls==1&&last==index&&!ui.TrySubmitPresentedOption(index,view.request.requestId):calls==0&&!ui.TrySubmitPresentedOption(index,view.request.requestId),"Choice identity/duplicate");File.AppendAllText(Output+"/steps.log",lang+" choice "+path+" acting="+acting+" PASS\n");
                }
                foreach(string path in abilityInputs){var view=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(path));ui.Present(view,view.seat,false,null,null,"");yield return Frame();foreach(var entry in view.stackItems.Where(e=>e.source?.helperArtName=="The Ring")){int index=Array.FindIndex(view.stackItems,e=>e.id==entry.id);var face=Root.GetComponentsInChildren<Transform>().Single(t=>t.name=="StackCard_"+index).Find("AbilityFace");Check(face.Find("Name").GetComponent<Text>().text==(lang=="zh-CN"?"魔戒":lang=="ja-JP"?"指輪":"The Ring"),"Stack Ring name");Check(SpecialEffectArt.TryLoad("The Ring",out var sprite)&&face.Find("Art").GetComponent<RawImage>().texture==sprite.texture,"Stack Ring art");string text=face.Find("EffectClip/Effect").GetComponent<Text>().text;Check(lang=="en-US"||!text.Contains("Whenever")&&!text.Contains("At end of combat"),"Stack known paragraph English: "+text);foreach(var match in System.Text.RegularExpressions.Regex.Matches(entry.description,@"\((\d+)\)").Cast<System.Text.RegularExpressions.Match>())Check(text.Contains(match.Value),"Stack event identity discarded");}File.AppendAllText(Output+"/steps.log",lang+" ability "+path+" PASS\n");}
            }
            var a=new ForgeCardView{printingKey="same",currentType="Legendary Creature",id=1};var b=new ForgeCardView{printingKey="same",currentType="Legendary Creature",id=2};Check(ForgeBattlefieldController.ArenaGroupKey(a)==ForgeBattlefieldController.ArenaGroupKey(b),"Ordinary grouping changed");a.ringBearer=true;Check(ForgeBattlefieldController.ArenaGroupKey(a)!=ForgeBattlefieldController.ArenaGroupKey(b),"Already-legendary bearer wrongly grouped");
        }finally{ui.Present(null,1,false,null,null,"");ui.enabled=enabled;GamePreferences.SetLanguage(language);if(module!=null)module.enabled=active;}
    }
}
#endif
